5:test.describe("grades editable", () => {
6:  test("grades editable", { tag: '@functionality' }, async ({ browser }) => {
146:  test("grades editable scenario 1", { tag: '@functionality' }, async ({ browser }) => {
623:  test("grades editable scenario 2", { tag: '@functionality' }, async ({ browser }) => {
1274:  test("grades editable scenario 3", { tag: '@functionality' }, async ({ browser }) => {
import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("grades editable", () => {
  test("grades editable", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.addGrade(pg_uma, "D")).toBe(true);
    expect(await ui.addGrade(pg_uma, "D")).toBe(false);
    expect(await ui.addGrade(pg_uma, "dd")).toBe(false);
    expect(await ui.addGrade(pg_uma, "ABCD")).toBe(false);
    expect(await ui.addGrade(pg_uma, "E1")).toBe(false);
    expect(await ui.addGrade(pg_uma, " XY ")).toBe(true);
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "D"}));
    expect(await ui.setRate(pg_uma, {"grade": "D", "pct": "40.00"})).toBe(true);
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.00"}));
    expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
    expect(await ui.editPerson(pg_uma, p_ada, {"grade": "XY"})).toBe(true);
    const c_cam_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "1.00"}));
    const p_cam = await ui.personId(pg_uma, "Cam");
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-name")).toHaveText("Ada (XY)");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-grade")).toHaveText("XY");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-name")).toHaveText("Ben (D)");
